async def main():
    steps = {}
    async def g(svc, op, **kw):
        try:
            return await call_boto3(service_name=svc, operation_name=op, region_name="us-east-1", params=kw or None)
        except Exception as e:
            return {"error": str(e)}
    # wait for tasks to drain
    for i in range(60):
        t = await g("ecs","ListTasks", cluster="umami-acs446c206e")
        if not t.get("taskArns"):
            steps["tasks_drained_s"] = i*10
            break
        await asyncio.sleep(10)
    steps["dereg_td"] = await g("ecs","DeregisterTaskDefinition", taskDefinition="umami-acs446c206e:1")
    steps["del_td"] = await g("ecs","DeleteTaskDefinitions", taskDefinitions=["umami-acs446c206e:1"])
    steps["del_cluster"] = await g("ecs","DeleteCluster", cluster="umami-acs446c206e")
    steps["del_loggroup"] = await g("logs","DeleteLogGroup", logGroupName="/ecs/umami-acs446c206e")
    # security groups (may need ENI release)
    for sg in ["sg-0e31183c862b88cad","sg-0b40377ab17c8c1f0"]:
        for i in range(30):
            r = await g("ec2","DeleteSecurityGroup", GroupId=sg)
            if "error" not in r:
                steps[f"del_{sg}"] = "deleted"
                break
            steps[f"del_{sg}"] = r["error"][:150]
            await asyncio.sleep(10)
    # IAM role
    ap = await g("iam","ListAttachedRolePolicies", RoleName="umami-acs446c206e-exec")
    steps["attached"] = ap
    for p in ap.get("AttachedPolicies", []):
        steps[f"detach_{p['PolicyName']}"] = await g("iam","DetachRolePolicy", RoleName="umami-acs446c206e-exec", PolicyArn=p["PolicyArn"])
    ip = await g("iam","ListRolePolicies", RoleName="umami-acs446c206e-exec")
    steps["inline"] = ip
    for pn in ip.get("PolicyNames", []):
        steps[f"delinline_{pn}"] = await g("iam","DeleteRolePolicy", RoleName="umami-acs446c206e-exec", PolicyName=pn)
    steps["del_role"] = await g("iam","DeleteRole", RoleName="umami-acs446c206e-exec")
    return steps
